use std::{fs, path::Path, process::Command};
use textintel::core::providers::G2PProvider;
use textintel::phonetic::{EspeakNgG2PProvider, parse_espeak_ipa};
fn main() {
    let binary=std::env::args().nth(1).expect("binary path");
    let provider=EspeakNgG2PProvider::new().with_binary(&binary);
    let output=Path::new("target/tools/espeak-audit/negative-literal");
    fs::create_dir_all(output).unwrap();
    for (index,source) in ["--help","-12","-vfr"].into_iter().enumerate() {
        let before=Command::new(&binary).args(["-q","--ipa=3","-v","en",source]).output().unwrap();
        let guarded=Command::new(&binary).args(["-q","--ipa=3","-v","en","--",source]).output().unwrap();
        fs::write(output.join(format!("{index}-before.stdout")),&before.stdout).unwrap();
        fs::write(output.join(format!("{index}-before.stderr")),&before.stderr).unwrap();
        fs::write(output.join(format!("{index}-guarded.stdout")),&guarded.stdout).unwrap();
        fs::write(output.join(format!("{index}-guarded.stderr")),&guarded.stderr).unwrap();
        let expected=parse_espeak_ipa(&String::from_utf8(guarded.stdout).unwrap()).0;
        let candidate=provider.phonemize(source,"en").unwrap();
        let ipa=candidate.ipa.unwrap_or_default();
        assert_eq!(candidate.source,source);
        assert_eq!(ipa,expected);
        assert!(!ipa.is_empty());
        assert!(!candidate.phonemes.is_empty());
        println!("OK\t{source}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{ipa}",before.status.code().unwrap_or(-1),guarded.status.code().unwrap_or(-1),candidate.source==source,ipa==expected,candidate.dialect.unwrap_or_default(),candidate.confidence,candidate.phonemes.len());
    }
}

