use textintel::core::providers::G2PProvider;
use textintel::phonetic::EspeakNgG2PProvider;
use textintel::speech::{SpeechLocale, locales};

fn main() {
    let binary = std::env::args().nth(1).expect("binary path");
    let provider = EspeakNgG2PProvider::new().with_binary(&binary);
    match provider.installed_voices() {
        Ok(voices) => println!("VOICES\t{}", voices.len()),
        Err(error) => println!("VOICES_ERROR\t{error}"),
    }
    let samples = [
        ("en", "The small boat crossed the quiet river."),
        ("es", "La biblioteca abre temprano cada mañana."),
        ("zh", "清晨的阳光照进安静的房间。"),
        ("hi", "बच्चे बगीचे में रंगीन फूल देख रहे हैं।"),
        ("ar", "تفتح المكتبة أبوابها في الصباح الباكر."),
        ("fr", "Le jardin devient calme après la pluie."),
        ("pt", "As crianças caminham perto da biblioteca."),
        ("ru", "Утром над рекой поднимается лёгкий туман."),
        ("bn", "সকালে নদীর পাশে পাখিরা গান গায়।"),
        ("ur", "صبح کے وقت باغ میں پرندے گاتے ہیں۔"),
        ("id", "Anak-anak membaca buku di taman."),
        ("de", "Am Morgen liegt Nebel über dem Fluss."),
        ("ja", "静かな庭で小さな鳥が歌っています。"),
        ("pa", "ਸਵੇਰੇ ਬਾਗ ਵਿੱਚ ਪੰਛੀ ਗਾਉਂਦੇ ਹਨ।"),
        ("mr", "सकाळी बागेत पक्षी गाणी गातात."),
        ("te", "ఉదయం తోటలో పక్షులు పాటలు పాడుతున్నాయి."),
        ("tr", "Çocuklar bahçede sessizce kitap okuyor."),
        ("ta", "காலையில் தோட்டத்தில் பறவைகள் பாடுகின்றன."),
        ("vi", "Buổi sáng, những chú chim hót trong vườn."),
        ("ko", "아침에 작은 새들이 정원에서 노래합니다."),
    ];
    for locale in SpeechLocale::ALL {
        let code = locale.code();
        let source = samples.iter().find(|(language, _)| *language == code).unwrap().1;
        let profile = locales::for_language(code).unwrap();
        let mut tags = Vec::new();
        for tag in std::iter::once(code).chain(std::iter::once(profile.default_locale)).chain(profile.typed_aliases.iter().copied()) {
            if !tags.contains(&tag) { tags.push(tag); }
        }
        for tag in tags {
            let voice = provider.voice_for(tag);
            match provider.phonemize(source, tag) {
                Ok(candidate) => println!("OK\t{code}\t{tag}\t{voice}\t{}\t{}\t{}\t{}\t{}", candidate.confidence, candidate.phonemes.len(), candidate.syllables, source, candidate.ipa.unwrap_or_default().replace(['\n','\t'], " ")),
                Err(error) => println!("ERROR\t{code}\t{tag}\t{voice}\t{source}\t{error}"),
            }
        }
    }
}

