use textintel::core::providers::G2PProvider;
use textintel::phonetic::EspeakNgG2PProvider;
fn main() {
    let binary=std::env::args().nth(1).expect("binary path");
    let provider=EspeakNgG2PProvider::new().with_binary(binary).for_voice("es-419");
    println!("CAPABILITIES\t{}",provider.capabilities().languages.join(","));
    for (tag,text) in [("es-MX","La casa es pequeña."),("fr","La maison est petite.")] {
        match provider.phonemize(text,tag) {
            Ok(candidate)=>println!("OK\t{tag}\t{}\t{}\t{}\t{text}\t{}",provider.voice_for(tag),candidate.dialect.unwrap_or_default(),candidate.confidence,candidate.ipa.unwrap_or_default()),
            Err(error)=>println!("ERROR\t{tag}\t{text}\t{error}"),
        }
    }
}
